from collections import Counter, defaultdict

def transform(grid):
    h, w = len(grid), len(grid[0])

    # The repeated pattern occupies the area below and to the right of
    # the top and left borders.
    data = [(r + c, grid[r][c])
            for r in range(3, h)
            for c in range(3, w)
            if grid[r][c] != 0]

    fits = []
    for period in range(2, 11):
        counts = defaultdict(Counter)
        for pos, value in data:
            counts[pos % period][value] += 1
        score = sum(max(counter.values()) for counter in counts.values())
        fits.append((period, score, counts))

    best_score = max(score for _, score, _ in fits)
    tolerance = max(2, len(data) // 50)
    period, _, counts = min(
        (fit for fit in fits if fit[1] >= best_score - tolerance),
        key=lambda fit: fit[0]
    )
    pattern = {residue: counter.most_common(1)[0][0]
               for residue, counter in counts.items()}

    frame_color = Counter(v for v in grid[2][2:] if v != 0).most_common(1)[0][0]
    background = Counter(v for v in grid[0] if v != 0).most_common(1)[0][0]

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = background
            elif r == 2 or c == 2:
                out[r][c] = frame_color
            else:
                out[r][c] = pattern[(r + c) % period]
    return out
